import { IngestPipeline } from "@514labs/moose-lib";

// Data model for events
export interface Event {
  event_id: string;
  event_ts: Date;
  user_id: string;
  event_type: string;
  value: number;
}

// Ingest pipeline for events
export const EventPipeline = new IngestPipeline<Event>("Event", {
  table: { orderByFields: ["event_ts", "user_id"] },
  stream: true,
  ingestApi: true,
});

