  if (!valueStr || valueStr === 'N/A' || valueStr === 'null' || valueStr.trim() === '') {
    return 0.0;
  }
  return parseFloat(valueStr);
}

// Function to process a single CSV file
function processCSV(filePath) {
  console.log(`Processing ${filePath}...`);
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.trim().split('\n');

  const events = [];
  let headerFound = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Skip header lines
    if (line.startsWith('event_id,event_ts,user_id,event_type,value')) {
      headerFound = true;
      continue;
    }

    if (!headerFound) continue;

    // Remove trailing comma if present
    const cleanedLine = line.replace(/,$/, '');
    const [event_id, event_ts, user_id, event_type, value] = cleanedLine.split(',');

    try {
      const event = {
        event_id: event_id.trim(),
        event_ts: parseDate(event_ts.trim()),
        user_id: user_id.trim(),
        event_type: event_type.trim(),
        value: cleanValue(value ? value.trim() : '')
      };

      events.push(event);
      console.log(`  Processed: ${event.event_id} (${event.event_type}) - ${event.value}`);
    } catch (error) {
      console.error(`  Error processing line ${i + 1}: ${error.message}`);
      console.error(`  Line content: ${line}`);
    }
  }

  return events;
}

// Function to send events to Moose using curl
function sendToMoose(events) {
  console.log(`\nSending ${events.length} events to Moose...`);

  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    try {
      const jsonData = JSON.stringify(event);
      const tempFile = `/tmp/event_${i}.json`;
      fs.writeFileSync(tempFile, jsonData);

      const curlCommand = `curl -s -X POST "http://localhost:4000/ingest/Event" -H "Content-Type: application/json" -d @${tempFile}`;
      const result = execSync(curlCommand, { encoding: 'utf-8' });

      console.log(`  ✓ Sent event ${event.event_id}: ${result.trim()}`);
      fs.unlinkSync(tempFile);
    } catch (error) {
      console.error(`Error sending event ${event.event_id}:`, error.message);
    }
  }
}

// Main execution
function main() {
  const csvDir = '/data/csv';
  const csvFiles = fs.readdirSync(csvDir).filter(f => f.endsWith('.csv')).sort();

  console.log('Found CSV files:', csvFiles);

  let allEvents = [];

  // Process each CSV file
  for (const file of csvFiles) {
    const filePath = path.join(csvDir, file);
    const events = processCSV(filePath);
    allEvents.push(...events);
  }

  console.log(`\nTotal events processed: ${allEvents.length}`);

  // Send to Moose
  sendToMoose(allEvents);

  console.log('\nData loading complete!');
}

main();

